    ct, _ = ContentType.objects.get_or_create(app_label='maintenance', model='complaint')
    perm_mgr, _ = Permission.objects.get_or_create(
        codename='can_view_manager_complaint',
        content_type=ct,
        defaults={'name': 'Can view manager complaints against workers'}
    )
    perm_wkr, _ = Permission.objects.get_or_create(
        codename='can_view_worker_complaint',
        content_type=ct,
        defaults={'name': 'Can view worker complaints against managers'}
    )

    manager_groups = ['Store Manager', 'Area Manager', 'Office Administrator', 'Management']
    for g_name in manager_groups:
        try:
            group = Group.objects.get(name=g_name)
            group.permissions.add(perm_mgr)
        except Exception:
            pass

    worker_groups = ['Technician', 'Office Administrator', 'Management']
    for g_name in worker_groups:
        try:
            group = Group.objects.get(name=g_name)
            group.permissions.add(perm_wkr)
        except Exception:
            pass


